// ***************
// Filename: npu_regs.sv
// Author: FPGA Cores 4 U
// Description: Register map of npu: its AXI4-Lite register slave
//   (axi4_lite_slave front end) with every register of the block, the ID
//   block first; the registers go to npu's logic on named ports, its status
//   comes back on input ports. INT8 neural-network accelerator: frame writer
//   to DDR, command processor (64-byte layer descriptors), 64 x 64 MAC array,
//   decode of detections (golden model: ip/ai/npu/model/npu_model.py).
//   Generated by ip/scripts/regmap_gen.py from npu_regs.json: edit the JSON
//   and regenerate (the IP_VERSION / IP_DATE stamps are kept).
//   Register map (ADDR_W = 8, byte offsets):
//     0x00 ID          RO   "NPU8" IP identifier, 4 ASCII characters (first
//                       in [31:24])
//     0x04 VERSION     RO   version, ASCII "d.dd" (+0.01 at every source
//                       update)
//     0x08 DATE        RO   date of the last source update, BCD mm/dd/yyyy
//                       (0xMMDDYYYY)
//     0x0C reserved    RO   0
//     0x10 CTRL        RW   control, reset 0x0
//                       [0] EN: on
//                       [1] AUTO: start a run on every frame the frame writer
//                         completes
//                       [2] WRITE: frame writer on: every input frame
//                         (RGB888) to FRAME_ADDR, FRAME_STRIDE bytes per line
//     0x14 CMD         WO   write 1: start a run now (ignored while busy)
//                       [0] START: start
//     0x18 STATUS      RO   state
//                       [0] BUSY: a run in progress
//                       [1] FRAME: a frame was written since the last run
//                         started
//     0x1C IRQ_EN      RW   interrupt enables, reset 0x0
//                       [0] DONE: run done
//                       [1] ERROR: bad descriptor
//     0x20 IRQ_STATUS  W1C  interrupt status; write 1 to clear, reset 0x0
//                       [0] DONE: run done
//                       [1] ERROR: bad descriptor (unknown operation)
//     0x24 DESC_ADDR   RW   DDR address of the first layer descriptor, reset
//                       0x0
//     0x28 DET_ADDR    RW   DDR address of the detection list (16 bytes per
//                       detection), reset 0x0
//     0x2C DET_MAX     RW   most detections written, reset 0x40
//     0x30 DET_COUNT   RO   detections written by the last run
//     0x34 FRAME_ADDR  RW   DDR address of the frame buffer (frame writer,
//                       INPUT operation), reset 0x0
//     0x38 FRAME_STRIDE RW   bytes per frame buffer line, reset 0x0
//     0x3C FRAME_SIZE  RW   frame size, reset 0x0
//                       [15:0] WIDTH: pixels
//                       [31:16] HEIGHT: lines
//     0x40 LB_STEP     RW   letterbox: frame pixels per network input pixel,
//                       Q16 (bilinear scaling), reset 0x0
//     0x44 LB_OFFSET   RW   letterbox: top-left of the picture in the network
//                       input, reset 0x0
//                       [15:0] X: column
//                       [31:16] Y: line
//     0x48 LB_SIZE     RW   letterbox: picture size in the network input,
//                       reset 0x0
//                       [15:0] WIDTH: pixels
//                       [31:16] HEIGHT: lines
//     0x4C LB_INV      RW   decode: frame pixels per network input pixel, Q16
//                       (detections in frame pixels), reset 0x0
//     0x50 CYCLES      RO   clocks of the last run
//     0x54 RUNS        RO   runs completed
//     0x58 LB2_STEP    RW   second letterbox (INPUT / DECODE with descriptor
//                       flag BANK2: the low-resolution pass for large
//                       objects): as LB_STEP, reset 0x0
//     0x5C LB2_OFFSET  RW   second letterbox: as LB_OFFSET, reset 0x0
//                       [15:0] X: column
//                       [31:16] Y: line
//     0x60 LB2_SIZE    RW   second letterbox: as LB_SIZE, reset 0x0
//                       [15:0] WIDTH: pixels
//                       [31:16] HEIGHT: lines
//     0x64 LB2_INV     RW   second letterbox: as LB_INV, reset 0x0
//   Access: RW read / write (byte strobes), RO read only (writes answer
//   SLVERR), W1C hardware sets / software writes 1 to clear (a set wins), W1S
//   software writes 1 to set / hardware clears, WO write only (reads 0), CMD
//   reads the hardware value, a write gives a pulse with its data. Unmapped
//   words read 0 and ignore writes; above the map: DECERR. Clock - clk. Reset
//   - synchronous active low rst_n. Latency - 2 clocks per write and read.
// Date: 2026-10-26
module npu_regs (
  input  logic          clk,               // clock
  input  logic          rst_n,             // synchronous reset, active low
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  axil_if.slave s_axil,
  // r: npu_regs_if.regs (src/include/npu_regs_if.sv) {ctrl_o=cfg_ctrl ctrl_wr_o=cfg_ctrl_wr cmd_o=cfg_cmd cmd_wr_o=cfg_cmd_wr status_i=sts_status irq_en_o=cfg_irq_en irq_en_wr_o=cfg_irq_en_wr irq_status_o=cfg_irq_status irq_status_wr_o=cfg_irq_status_wr irq_status_set_i=sts_irq_status_set desc_addr_o=cfg_desc_addr desc_addr_wr_o=cfg_desc_addr_wr det_addr_o=cfg_det_addr det_addr_wr_o=cfg_det_addr_wr det_max_o=cfg_det_max det_max_wr_o=cfg_det_max_wr det_count_i=sts_det_count frame_addr_o=cfg_frame_addr frame_addr_wr_o=cfg_frame_addr_wr frame_stride_o=cfg_frame_stride frame_stride_wr_o=cfg_frame_stride_wr frame_size_o=cfg_frame_size frame_size_wr_o=cfg_frame_size_wr lb_step_o=cfg_lb_step lb_step_wr_o=cfg_lb_step_wr lb_offset_o=cfg_lb_offset lb_offset_wr_o=cfg_lb_offset_wr lb_size_o=cfg_lb_size lb_size_wr_o=cfg_lb_size_wr lb_inv_o=cfg_lb_inv lb_inv_wr_o=cfg_lb_inv_wr cycles_i=sts_cycles runs_i=sts_runs lb2_step_o=cfg_lb2_step lb2_step_wr_o=cfg_lb2_step_wr lb2_offset_o=cfg_lb2_offset lb2_offset_wr_o=cfg_lb2_offset_wr lb2_size_o=cfg_lb2_size lb2_size_wr_o=cfg_lb2_size_wr lb2_inv_o=cfg_lb2_inv lb2_inv_wr_o=cfg_lb2_inv_wr}
  npu_regs_if.regs r
);
  // register signals, joined to the interface r
  logic [3-1:0] ctrl_o;
  logic ctrl_wr_o;
  logic cmd_o;
  logic cmd_wr_o;
  logic [2-1:0] status_i;
  logic [2-1:0] irq_en_o;
  logic irq_en_wr_o;
  logic [2-1:0] irq_status_o;
  logic irq_status_wr_o;
  logic [2-1:0] irq_status_set_i;
  logic [32-1:0] desc_addr_o;
  logic desc_addr_wr_o;
  logic [32-1:0] det_addr_o;
  logic det_addr_wr_o;
  logic [16-1:0] det_max_o;
  logic det_max_wr_o;
  logic [16-1:0] det_count_i;
  logic [32-1:0] frame_addr_o;
  logic frame_addr_wr_o;
  logic [16-1:0] frame_stride_o;
  logic frame_stride_wr_o;
  logic [32-1:0] frame_size_o;
  logic frame_size_wr_o;
  logic [32-1:0] lb_step_o;
  logic lb_step_wr_o;
  logic [32-1:0] lb_offset_o;
  logic lb_offset_wr_o;
  logic [32-1:0] lb_size_o;
  logic lb_size_wr_o;
  logic [32-1:0] lb_inv_o;
  logic lb_inv_wr_o;
  logic [32-1:0] cycles_i;
  logic [32-1:0] runs_i;
  logic [32-1:0] lb2_step_o;
  logic lb2_step_wr_o;
  logic [32-1:0] lb2_offset_o;
  logic lb2_offset_wr_o;
  logic [32-1:0] lb2_size_o;
  logic lb2_size_wr_o;
  logic [32-1:0] lb2_inv_o;
  logic lb2_inv_wr_o;
  assign r.cfg_ctrl = ctrl_o;
  assign r.cfg_ctrl_wr = ctrl_wr_o;
  assign r.cfg_cmd = cmd_o;
  assign r.cfg_cmd_wr = cmd_wr_o;
  assign status_i = r.sts_status;
  assign r.cfg_irq_en = irq_en_o;
  assign r.cfg_irq_en_wr = irq_en_wr_o;
  assign r.cfg_irq_status = irq_status_o;
  assign r.cfg_irq_status_wr = irq_status_wr_o;
  assign irq_status_set_i = r.sts_irq_status_set;
  assign r.cfg_desc_addr = desc_addr_o;
  assign r.cfg_desc_addr_wr = desc_addr_wr_o;
  assign r.cfg_det_addr = det_addr_o;
  assign r.cfg_det_addr_wr = det_addr_wr_o;
  assign r.cfg_det_max = det_max_o;
  assign r.cfg_det_max_wr = det_max_wr_o;
  assign det_count_i = r.sts_det_count;
  assign r.cfg_frame_addr = frame_addr_o;
  assign r.cfg_frame_addr_wr = frame_addr_wr_o;
  assign r.cfg_frame_stride = frame_stride_o;
  assign r.cfg_frame_stride_wr = frame_stride_wr_o;
  assign r.cfg_frame_size = frame_size_o;
  assign r.cfg_frame_size_wr = frame_size_wr_o;
  assign r.cfg_lb_step = lb_step_o;
  assign r.cfg_lb_step_wr = lb_step_wr_o;
  assign r.cfg_lb_offset = lb_offset_o;
  assign r.cfg_lb_offset_wr = lb_offset_wr_o;
  assign r.cfg_lb_size = lb_size_o;
  assign r.cfg_lb_size_wr = lb_size_wr_o;
  assign r.cfg_lb_inv = lb_inv_o;
  assign r.cfg_lb_inv_wr = lb_inv_wr_o;
  assign cycles_i = r.sts_cycles;
  assign runs_i = r.sts_runs;
  assign r.cfg_lb2_step = lb2_step_o;
  assign r.cfg_lb2_step_wr = lb2_step_wr_o;
  assign r.cfg_lb2_offset = lb2_offset_o;
  assign r.cfg_lb2_offset_wr = lb2_offset_wr_o;
  assign r.cfg_lb2_size = lb2_size_o;
  assign r.cfg_lb2_size_wr = lb2_size_wr_o;
  assign r.cfg_lb2_inv = lb2_inv_o;
  assign r.cfg_lb2_inv_wr = lb2_inv_wr_o;
  // ---------------- register map
  localparam logic [31:0] IP_ID      = "NPU8";
  localparam logic [31:0] IP_VERSION = "0.11";
  localparam logic [31:0] IP_DATE    = 32'h10252026;   // mm/dd/yyyy, BCD
  localparam logic [7:0] A_ID = 8'h0, A_VERSION = 8'h4, A_DATE = 8'h8;
  localparam logic [7:0] A_CTRL = 8'h10;
  localparam logic [7:0] A_CMD = 8'h14;
  localparam logic [7:0] A_STATUS = 8'h18;
  localparam logic [7:0] A_IRQ_EN = 8'h1C;
  localparam logic [7:0] A_IRQ_STATUS = 8'h20;
  localparam logic [7:0] A_DESC_ADDR = 8'h24;
  localparam logic [7:0] A_DET_ADDR = 8'h28;
  localparam logic [7:0] A_DET_MAX = 8'h2C;
  localparam logic [7:0] A_DET_COUNT = 8'h30;
  localparam logic [7:0] A_FRAME_ADDR = 8'h34;
  localparam logic [7:0] A_FRAME_STRIDE = 8'h38;
  localparam logic [7:0] A_FRAME_SIZE = 8'h3C;
  localparam logic [7:0] A_LB_STEP = 8'h40;
  localparam logic [7:0] A_LB_OFFSET = 8'h44;
  localparam logic [7:0] A_LB_SIZE = 8'h48;
  localparam logic [7:0] A_LB_INV = 8'h4C;
  localparam logic [7:0] A_CYCLES = 8'h50;
  localparam logic [7:0] A_RUNS = 8'h54;
  localparam logic [7:0] A_LB2_STEP = 8'h58;
  localparam logic [7:0] A_LB2_OFFSET = 8'h5C;
  localparam logic [7:0] A_LB2_SIZE = 8'h60;
  localparam logic [7:0] A_LB2_INV = 8'h64;
  localparam int MAP_WORDS = 26;

  logic             wr_en, rd_en, wr_err_q;
  logic [7:0]       wr_addr, rd_addr, rd_addr_q;
  wire unused_addr_lsbs = &{1'b0, wr_addr[1:0], rd_addr[1:0]};   // word access: the byte offset is not decoded
  logic [31:0]      wr_data, rd_data;
  logic [3:0]       wr_strb;
  regbus_if #(.ADDR_W(8)) bus ();               // register bus of the AXI4-Lite front end
  assign wr_en = bus.wr;
  assign wr_addr = bus.waddr;
  assign wr_data = bus.wdata;
  assign wr_strb = bus.wstrb;
  assign rd_en = bus.rd;
  assign rd_addr = bus.raddr;
  assign bus.wr_err = wr_err_q;
  assign bus.rdata = rd_data;
  assign bus.rd_valid = 1'b1;
  assign bus.rd_err = 1'b0;
  axi4_lite_slave #(
    .ADDR_W(8),
    .READ_WAIT(0),
    .MAP_WORDS(MAP_WORDS)
  ) u_axil (
    .aclk(clk),
    .aresetn(rst_n),
    .s_axil(s_axil),
    .bus(bus)
  );
  wire [7:0] wa = {wr_addr[7:2], 2'b00};
  // byte strobes applied to the written word
  logic [31:0] wmask;
  always_comb for (int b = 0; b < 4; b++) wmask[b*8 +: 8] = {8{wr_strb[b]}};

  // ---------------- writes
  logic [31:0] ctrl_q;
  logic [31:0] cmd_q;
  logic [31:0] irq_en_q;
  logic [31:0] irq_status_q;
  logic [31:0] desc_addr_q;
  logic [31:0] det_addr_q;
  logic [31:0] det_max_q;
  logic [31:0] frame_addr_q;
  logic [31:0] frame_stride_q;
  logic [31:0] frame_size_q;
  logic [31:0] lb_step_q;
  logic [31:0] lb_offset_q;
  logic [31:0] lb_size_q;
  logic [31:0] lb_inv_q;
  logic [31:0] lb2_step_q;
  logic [31:0] lb2_offset_q;
  logic [31:0] lb2_size_q;
  logic [31:0] lb2_inv_q;
  always_ff @(posedge clk) begin
    if (!rst_n) begin
      ctrl_q <= 32'h0;
      ctrl_wr_o <= 1'b0;
      cmd_q <= '0;
      cmd_wr_o <= 1'b0;
      irq_en_q <= 32'h0;
      irq_en_wr_o <= 1'b0;
      irq_status_q <= 32'h0;
      irq_status_wr_o <= 1'b0;
      desc_addr_q <= 32'h0;
      desc_addr_wr_o <= 1'b0;
      det_addr_q <= 32'h0;
      det_addr_wr_o <= 1'b0;
      det_max_q <= 32'h40;
      det_max_wr_o <= 1'b0;
      frame_addr_q <= 32'h0;
      frame_addr_wr_o <= 1'b0;
      frame_stride_q <= 32'h0;
      frame_stride_wr_o <= 1'b0;
      frame_size_q <= 32'h0;
      frame_size_wr_o <= 1'b0;
      lb_step_q <= 32'h0;
      lb_step_wr_o <= 1'b0;
      lb_offset_q <= 32'h0;
      lb_offset_wr_o <= 1'b0;
      lb_size_q <= 32'h0;
      lb_size_wr_o <= 1'b0;
      lb_inv_q <= 32'h0;
      lb_inv_wr_o <= 1'b0;
      lb2_step_q <= 32'h0;
      lb2_step_wr_o <= 1'b0;
      lb2_offset_q <= 32'h0;
      lb2_offset_wr_o <= 1'b0;
      lb2_size_q <= 32'h0;
      lb2_size_wr_o <= 1'b0;
      lb2_inv_q <= 32'h0;
      lb2_inv_wr_o <= 1'b0;
      wr_err_q <= 1'b0;
    end else begin
      wr_err_q <= wr_en && (wa == A_ID || wa == A_VERSION || wa == A_DATE || wa == A_STATUS || wa == A_DET_COUNT || wa == A_CYCLES || wa == A_RUNS);   // writes to read-only words: SLVERR
      begin
        ctrl_wr_o <= wr_en && wa == A_CTRL;
        if (wr_en && wa == A_CTRL) ctrl_q <= (ctrl_q & ~wmask) | (wr_data & wmask);
      end
      begin
        cmd_wr_o <= wr_en && wa == A_CMD;
        if (wr_en && wa == A_CMD) cmd_q <= (cmd_q & ~wmask) | (wr_data & wmask);
      end
      begin
        irq_en_wr_o <= wr_en && wa == A_IRQ_EN;
        if (wr_en && wa == A_IRQ_EN) irq_en_q <= (irq_en_q & ~wmask) | (wr_data & wmask);
      end
      begin
        irq_status_wr_o <= wr_en && wa == A_IRQ_STATUS;
        irq_status_q <= ((wr_en && wa == A_IRQ_STATUS) ? irq_status_q & ~(wr_data & wmask) : irq_status_q) | 32'(irq_status_set_i);   // a set wins over a clear
      end
      begin
        desc_addr_wr_o <= wr_en && wa == A_DESC_ADDR;
        if (wr_en && wa == A_DESC_ADDR) desc_addr_q <= (desc_addr_q & ~wmask) | (wr_data & wmask);
      end
      begin
        det_addr_wr_o <= wr_en && wa == A_DET_ADDR;
        if (wr_en && wa == A_DET_ADDR) det_addr_q <= (det_addr_q & ~wmask) | (wr_data & wmask);
      end
      begin
        det_max_wr_o <= wr_en && wa == A_DET_MAX;
        if (wr_en && wa == A_DET_MAX) det_max_q <= (det_max_q & ~wmask) | (wr_data & wmask);
      end
      begin
        frame_addr_wr_o <= wr_en && wa == A_FRAME_ADDR;
        if (wr_en && wa == A_FRAME_ADDR) frame_addr_q <= (frame_addr_q & ~wmask) | (wr_data & wmask);
      end
      begin
        frame_stride_wr_o <= wr_en && wa == A_FRAME_STRIDE;
        if (wr_en && wa == A_FRAME_STRIDE) frame_stride_q <= (frame_stride_q & ~wmask) | (wr_data & wmask);
      end
      begin
        frame_size_wr_o <= wr_en && wa == A_FRAME_SIZE;
        if (wr_en && wa == A_FRAME_SIZE) frame_size_q <= (frame_size_q & ~wmask) | (wr_data & wmask);
      end
      begin
        lb_step_wr_o <= wr_en && wa == A_LB_STEP;
        if (wr_en && wa == A_LB_STEP) lb_step_q <= (lb_step_q & ~wmask) | (wr_data & wmask);
      end
      begin
        lb_offset_wr_o <= wr_en && wa == A_LB_OFFSET;
        if (wr_en && wa == A_LB_OFFSET) lb_offset_q <= (lb_offset_q & ~wmask) | (wr_data & wmask);
      end
      begin
        lb_size_wr_o <= wr_en && wa == A_LB_SIZE;
        if (wr_en && wa == A_LB_SIZE) lb_size_q <= (lb_size_q & ~wmask) | (wr_data & wmask);
      end
      begin
        lb_inv_wr_o <= wr_en && wa == A_LB_INV;
        if (wr_en && wa == A_LB_INV) lb_inv_q <= (lb_inv_q & ~wmask) | (wr_data & wmask);
      end
      begin
        lb2_step_wr_o <= wr_en && wa == A_LB2_STEP;
        if (wr_en && wa == A_LB2_STEP) lb2_step_q <= (lb2_step_q & ~wmask) | (wr_data & wmask);
      end
      begin
        lb2_offset_wr_o <= wr_en && wa == A_LB2_OFFSET;
        if (wr_en && wa == A_LB2_OFFSET) lb2_offset_q <= (lb2_offset_q & ~wmask) | (wr_data & wmask);
      end
      begin
        lb2_size_wr_o <= wr_en && wa == A_LB2_SIZE;
        if (wr_en && wa == A_LB2_SIZE) lb2_size_q <= (lb2_size_q & ~wmask) | (wr_data & wmask);
      end
      begin
        lb2_inv_wr_o <= wr_en && wa == A_LB2_INV;
        if (wr_en && wa == A_LB2_INV) lb2_inv_q <= (lb2_inv_q & ~wmask) | (wr_data & wmask);
      end
    end
  end
  assign ctrl_o = ctrl_q[3-1:0];
  assign cmd_o = cmd_q[1-1:0];
  assign irq_en_o = irq_en_q[2-1:0];
  assign irq_status_o = irq_status_q[2-1:0];
  assign desc_addr_o = desc_addr_q[32-1:0];
  assign det_addr_o = det_addr_q[32-1:0];
  assign det_max_o = det_max_q[16-1:0];
  assign frame_addr_o = frame_addr_q[32-1:0];
  assign frame_stride_o = frame_stride_q[16-1:0];
  assign frame_size_o = frame_size_q[32-1:0];
  assign lb_step_o = lb_step_q[32-1:0];
  assign lb_offset_o = lb_offset_q[32-1:0];
  assign lb_size_o = lb_size_q[32-1:0];
  assign lb_inv_o = lb_inv_q[32-1:0];
  assign lb2_step_o = lb2_step_q[32-1:0];
  assign lb2_offset_o = lb2_offset_q[32-1:0];
  assign lb2_size_o = lb2_size_q[32-1:0];
  assign lb2_inv_o = lb2_inv_q[32-1:0];

  // ---------------- reads: the word addressed in the clock before
  always_ff @(posedge clk) if (rd_en) rd_addr_q <= {rd_addr[7:2], 2'b00};
  always_comb begin
    rd_data = '0;
    case (rd_addr_q)
      A_ID:      rd_data = IP_ID;
      A_VERSION: rd_data = IP_VERSION;
      A_DATE:    rd_data = IP_DATE;
      A_CTRL: rd_data = 32'(ctrl_q[3-1:0]);
      A_STATUS: rd_data = 32'(status_i);
      A_IRQ_EN: rd_data = 32'(irq_en_q[2-1:0]);
      A_IRQ_STATUS: rd_data = 32'(irq_status_q[2-1:0]);
      A_DESC_ADDR: rd_data = 32'(desc_addr_q[32-1:0]);
      A_DET_ADDR: rd_data = 32'(det_addr_q[32-1:0]);
      A_DET_MAX: rd_data = 32'(det_max_q[16-1:0]);
      A_DET_COUNT: rd_data = 32'(det_count_i);
      A_FRAME_ADDR: rd_data = 32'(frame_addr_q[32-1:0]);
      A_FRAME_STRIDE: rd_data = 32'(frame_stride_q[16-1:0]);
      A_FRAME_SIZE: rd_data = 32'(frame_size_q[32-1:0]);
      A_LB_STEP: rd_data = 32'(lb_step_q[32-1:0]);
      A_LB_OFFSET: rd_data = 32'(lb_offset_q[32-1:0]);
      A_LB_SIZE: rd_data = 32'(lb_size_q[32-1:0]);
      A_LB_INV: rd_data = 32'(lb_inv_q[32-1:0]);
      A_CYCLES: rd_data = 32'(cycles_i);
      A_RUNS: rd_data = 32'(runs_i);
      A_LB2_STEP: rd_data = 32'(lb2_step_q[32-1:0]);
      A_LB2_OFFSET: rd_data = 32'(lb2_offset_q[32-1:0]);
      A_LB2_SIZE: rd_data = 32'(lb2_size_q[32-1:0]);
      A_LB2_INV: rd_data = 32'(lb2_inv_q[32-1:0]);
      default: begin
      end
    endcase
  end
endmodule
